const KEY='takeoutHomePlanner_v1';
const VIEW_KEY='takeoutHomePlanner_view';
const VIEWS={
  plan:{title:'Weekly Plan',sub:'Assign meals to days · counts sync with shopping list',actions:'<button type="button" class="btn btn-secondary" id="openShopping">Shopping list</button>'},
  system:{title:'Meal System',sub:'Targets, cookware, weekday rules, and failure plans',actions:''},
  recipes:{title:'Recipes',sub:'Library and editor — each recipe rolls into your ingredient pantry',actions:''},
  ingredients:{title:'Ingredients + Links',sub:'Track unit, package price, and Aldi product URLs',actions:''},
  shopping:{title:'Shopping List',sub:'Auto-built from your plan — grouped by ingredient type',actions:''},
  backup:{title:'Import / Export',sub:'Back up recipes, plan, and ingredient prices',actions:''}
};
function showView(id){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  const panel=document.getElementById('view-'+id);
  if(panel)panel.classList.add('active');
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));
  const v=VIEWS[id]||VIEWS.plan;
  document.getElementById('view-title').textContent=v.title;
  document.getElementById('view-sub').textContent=v.sub;
  const actions=document.getElementById('topbar-actions');
  if(actions)actions.innerHTML=v.actions||'';
  try{localStorage.setItem(VIEW_KEY,id)}catch(e){}
  if(id==='shopping')renderShop();
  if(id==='ingredients')renderMeta();
  if(id==='backup')renderExport();
  if(id==='plan')renderPlan();
  updateSidebarFoot();
}
function updateSidebarFoot(){
  const el=document.getElementById('sidebar-foot');
  if(!el)return;
  const p=planned();
  const meals=p.reduce((s,x)=>s+x.c,0);
  const recipes=state.recipes.length;
  const {start,end}=weekRange(state.weekStart);
  el.textContent=`${formatShort(start)}–${formatShort(end)} · ${meals} meal${meals===1?'':'s'} · ${recipes} recipes`;
}
const DAY_NAMES=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
let pendingCalDate=null;
function calSlotId(){return 'cal-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
function formatDateISO(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function parseDateISO(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12,0,0)}
function getWeekStart(d){const x=new Date(d);const w=x.getDay();const diff=w===0?-6:1-w;x.setDate(x.getDate()+diff);return formatDateISO(x)}
function weekDates(weekStart){const start=parseDateISO(weekStart);return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return formatDateISO(d)})}
function weekRange(weekStart){const dates=weekDates(weekStart);return {start:parseDateISO(dates[0]),end:parseDateISO(dates[6])}}
function formatShort(d){return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function appState(s){return s||state}
function ensureCalendar(s){const st=appState(s);if(!Array.isArray(st.calendar))st.calendar=[];if(!st.weekStart)st.weekStart=getWeekStart(new Date())}
function calendarSlotCount(s){return (appState(s).calendar||[]).length}
function plannedFrom(s){const st=appState(s);let ids=new Set([...Object.keys(st.plan||{}),...Object.keys(st.planMeals||{})]);return [...ids].map(id=>({r:st.recipes.find(x=>x.id===id),c:totalMealsFrom(st,id)})).filter(x=>x.r&&x.c>0)}
function mealCountsFrom(s,id){const st=appState(s);st.planMeals=st.planMeals||{};let counts=st.planMeals[id];if(!counts){let r=st.recipes.find(x=>x.id===id),type=(st.planSlots||{})[id]||defaultMealType(r),total=Number((st.plan||{})[id])||0;counts=emptyMealCounts();counts[type]=total;st.planMeals[id]=counts}Object.keys(mealTypes).forEach(k=>counts[k]=Math.max(0,Number(counts[k])||0));return counts}
function plannedMealSlotCount(s){return plannedFrom(s).reduce((n,{c})=>n+c,0)}
function syncCalendarFromPlan(s){const st=appState(s);ensureCalendar(st);const dates=weekDates(st.weekStart),dateSet=new Set(dates);st.calendar=(st.calendar||[]).filter(sl=>!dateSet.has(sl.date));const slots=[];let dayIdx=0;plannedFrom(st).forEach(({r})=>{Object.keys(mealTypes).forEach(type=>{const n=Number(mealCountsFrom(st,r.id)[type])||0;for(let i=0;i<n;i++){slots.push({id:calSlotId(),date:dates[dayIdx%7],mealType:type,recipeId:r.id});dayIdx++}})});st.calendar.push(...slots)}
function addCalendarMeal(date,mealType,recipeId){ensureCalendar();state.calendar.push({id:calSlotId(),date,mealType,recipeId});const counts=mealCounts(recipeId);counts[mealType]=(Number(counts[mealType])||0)+1;syncPlanTotals()}
function removeCalendarSlot(id){const idx=(state.calendar||[]).findIndex(s=>s.id===id);if(idx<0)return;const slot=state.calendar[idx];state.calendar.splice(idx,1);const counts=mealCounts(slot.recipeId);counts[slot.mealType]=Math.max(0,(Number(counts[slot.mealType])||0)-1);syncPlanTotals()}
function shiftWeek(delta){ensureCalendar();const d=parseDateISO(state.weekStart);d.setDate(d.getDate()+delta*7);state.weekStart=formatDateISO(d)}
function openCalendarPicker(date){pendingCalDate=date;const sel=document.getElementById('cal-pick-recipe'),typeSel=document.getElementById('cal-pick-type');if(!sel)return;sel.innerHTML=state.recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');const first=state.recipes[0];if(first)typeSel.value=defaultMealType(first);document.getElementById('cal-dialog')?.showModal()}
function renderPlanSummary(){const el=document.getElementById('planSummary');if(!el)return;const meals=planned().reduce((s,x)=>s+x.c,0),items=shopping(),total=items.reduce((sum,i)=>sum+(itemCost(i)||0),0);el.innerHTML=`<div class="summary-item"><div class="label">Meals planned</div><div class="value num">${meals}</div></div><div class="summary-item"><div class="label">Shopping items</div><div class="value num">${items.length}</div></div><div class="summary-item"><div class="label">Est. grocery</div><div class="value num">${money(total)}</div></div>`}
function renderCalendar(){ensureCalendar();const el=document.getElementById('weekCalendar'),label=document.getElementById('weekLabel');if(!el)return;if(calendarSlotCount()<plannedMealSlotCount())syncCalendarFromPlan();const dates=weekDates(state.weekStart);if(label){const {start,end}=weekRange(state.weekStart);label.textContent=`${formatShort(start)} – ${formatShort(end)}`}el.innerHTML=dates.map((date,i)=>{const d=parseDateISO(date),slots=(state.calendar||[]).filter(s=>s.date===date);const slotHtml=slots.map(s=>{const r=state.recipes.find(x=>x.id===s.recipeId);const name=r?r.name:'Unknown recipe';return `<div class="meal-slot filled"><button type="button" class="slot-remove" data-cal-remove="${esc(s.id)}" aria-label="Remove">×</button><div class="meal-type">${esc(mealTypes[s.mealType]||s.mealType)}</div><strong>${esc(name)}</strong></div>`}).join('');return `<div class="day-col" role="gridcell"><div class="day-head"><span class="meta">${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong></div><div class="day-meals">${slotHtml}<button type="button" class="meal-slot add-slot" data-cal-add="${esc(date)}">+ Add</button></div></div>`}).join('')}
function tab(id){showView(id)}
